import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AddCurso = ({ onNavigate }) => {
  const [nome, setNome] = useState(""); // Adiciona nome do aluno
  const [curso, setCurso] = useState("Programação");
  const [nivel, setNivel] = useState("1");
  const [periodo, setPeriodo] = useState("Manhã");

  const handleSave = async () => {
    const dados = { nome, curso, nivel, periodo };

    try {
      const resposta = await fetch("http://localhost:5000/alunos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(dados),
      });

      if (resposta.ok) {
        alert("Aluno cadastrado com sucesso!");
        onNavigate("list");
      } else {
        alert("Erro ao cadastrar aluno.");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active" href="#">
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a className="nav-link" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Nova Inscrição</h2>

      <div
        className="card p-4 shadow-sm w-50"
        style={{ backgroundColor: "#F8F9FA" }}
      >
        <div className="mb-3">
          <label className="form-label fw-bold">Nome</label>
          <input
            type="text"
            className="form-control"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
          />
        </div>
        <div className="mb-3">
          <label className="form-label fw-bold">Curso</label>
          <select
            className="form-select"
            value={curso}
            onChange={(e) => setCurso(e.target.value)}
          >
            <option>Programação</option>
            <option>Contabilidade</option>
          </select>
        </div>
        <div className="mb-3">
          <label className="form-label fw-bold">Nível</label>
          <select
            className="form-select"
            value={nivel}
            onChange={(e) => setNivel(e.target.value)}
          >
            <option>1</option>
            <option>2</option>
          </select>
        </div>
        <div className="mb-3">
          <label className="form-label fw-bold">Período</label>
          <select
            className="form-select"
            value={periodo}
            onChange={(e) => setPeriodo(e.target.value)}
          >
            <option>Manhã</option>
            <option>Tarde</option>
          </select>
        </div>
        <div className="d-flex justify-content-between">
          <button
            className="btn text-white"
            style={{ backgroundColor: "#D9534F" }}
            onClick={() => onNavigate("list")}
          >
            Cancelar
          </button>
          <button
            className="btn text-white"
            style={{ backgroundColor: "#5A79BA" }}
            onClick={handleSave}
          >
            Salvar
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddCurso;
